#include <cctype>
#include <set>
#include <string>
#include <vector>

std::vector<std::string> missingImGuiFiles(const std::vector<std::string>& projectFiles)
{
    static const std::vector<std::string> required{ "imgui.cpp", "imgui_draw.cpp", "imgui_tables.cpp", "imgui_widgets.cpp", "imgui_impl_win32.cpp", "imgui_impl_dx11.cpp" };
    std::set<std::string> have;
    for (const std::string& f : projectFiles)
    {
        const auto slash{ f.find_last_of("/\\") };
        std::string name{ slash == std::string::npos ? f : f.substr(slash + 1) };
        for (char& c : name) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        have.insert(name);
    }
    std::vector<std::string> missing;
    for (const std::string& r : required) if (!have.count(r)) missing.push_back(r);
    return missing;
}

