using Names = std::vector<std::string>;
TEST("all present") { CHECK(missingImGuiFiles({ "imgui/imgui.cpp", "imgui/imgui_draw.cpp", "imgui/imgui_tables.cpp", "imgui/imgui_widgets.cpp", "imgui\\backends\\imgui_impl_win32.cpp", "imgui\\backends\\imgui_impl_dx11.cpp", "main.cpp" }).empty()); }
TEST("missing tables and a back end") { CHECK_EQ(missingImGuiFiles({ "imgui.cpp", "imgui_draw.cpp", "imgui_widgets.cpp", "imgui_impl_win32.cpp" }), (Names{ "imgui_tables.cpp", "imgui_impl_dx11.cpp" })); }
TEST("case does not matter") { CHECK(missingImGuiFiles({ "IMGUI.CPP", "Imgui_Draw.cpp", "imgui_tables.CPP", "imgui_widgets.cpp", "IMGUI_IMPL_WIN32.cpp", "imgui_impl_DX11.cpp" }).empty()); }
TEST("nothing") { CHECK_EQ(missingImGuiFiles({}).size(), std::size_t{ 6 }); }

